import hashlib
import multiprocessing as mp
import os
from concurrent.futures import ProcessPoolExecutor
from multiprocessing import shared_memory

def _process_batch(items: list[bytes]) -> list[str]:
    out = []
    for item in items:
        # CPU-bound Python canonicalization + SHA-256
        normalized = item.strip().lower()
        out.append(hashlib.sha256(normalized).hexdigest())
    return out

def _process_large_shm(args: tuple[str, int]) -> str:
    shm_name, size = args
    shm = shared_memory.SharedMemory(name=shm_name)
    try:
        view = memoryview(shm.buf)[:size]
        return hashlib.sha256(view).hexdigest()
    finally:
        shm.close()

def run_parallel_batches(batches: list[list[bytes]]) -> list[list[str]]:
    ctx = mp.get_context("spawn")
    workers = os.cpu_count() or 4
    with ProcessPoolExecutor(max_workers=workers, mp_context=ctx, max_tasks_per_child=1000) as pool:
        return list(pool.map(_process_batch, batches))

def hash_large_buffer_zero_copy(pool: ProcessPoolExecutor, data: bytes) -> str:
    shm = shared_memory.SharedMemory(create=True, size=len(data))
    try:
        shm.buf[:len(data)] = data
        return pool.submit(_process_large_shm, (shm.name, len(data))).result()
    finally:
        shm.close()
        shm.unlink()
